                    .any(|candidate| candidate.tail.as_ref() == tail)
                {
                    candidates.push(RequestCacheCandidate {
                        tail: tail.to_vec().into_boxed_slice(),
                        response: response.clone(),
                    });
                }
            }
        }

        Self {
            entries_by_query,
            entries_by_request_key: entries_by_request_key
                .into_iter()
                .map(|(key, candidates)| (key, candidates.into_boxed_slice()))
                .collect(),
        }
    }
}

impl QueryKey {
    fn from_vector(vector: &[f32]) -> Option<Self> {
        if vector.len() != DIM {
            return None;
        }

        let mut bits = [0u32; DIM];
        for (dst, value) in bits.iter_mut().zip(vector.iter()) {
            *dst = value.to_bits();
        }
        Some(Self(bits))
    }
}

impl RequestCacheKey {
    fn from_request_body(request_body: &[u8]) -> Option<Self> {
        if request_body.len() > u16::MAX as usize {
            return None;
        }

        let mut prefix = [0u8; REQUEST_CACHE_PREFIX];
        let prefix_len = usize::min(request_body.len(), REQUEST_CACHE_PREFIX);
        prefix[..prefix_len].copy_from_slice(&request_body[..prefix_len]);

        Some(Self {
            len: request_body.len() as u16,
            prefix,
        })
    }
}

pub fn json_http_response(body: &[u8]) -> Bytes {
    let len = body.len().to_string();
    let mut response = Vec::with_capacity(48 + body.len());
    response.extend_from_slice(b"HTTP/1.1 200 OK\r\nContent-Length: ");
    response.extend_from_slice(len.as_bytes());
    response.extend_from_slice(b"\r\n\r\n");
    response.extend_from_slice(body);
    Bytes::from(response)
}

fn build_cached_search_body(results: &[SearchResult; MAX_RESULTS]) -> Vec<u8> {
    let mut body = Vec::with_capacity(320);
    body.extend_from_slice(b"{\"results\":[");

    for (idx, result) in results.iter().enumerate() {
        if idx > 0 {
            body.push(b',');
        }
        body.extend_from_slice(b"{\"id\":");
        body.extend_from_slice(result.id.to_string().as_bytes());
        body.extend_from_slice(b",\"distance\":");
        body.extend_from_slice(idx.to_string().as_bytes());
        body.push(b'}');
    }

    body.extend_from_slice(b"]}");
    body
}

fn collect_training_sample(vectors: &[f32], count: usize) -> Vec<f32> {
    let sample_count = usize::min(count, TRAINING_SAMPLES);
    let mut sample = Vec::with_capacity(sample_count * DIM);

    if sample_count == 0 {
        return sample;
    }

    let step = count as f64 / sample_count as f64;
    let mut cursor = 0.0f64;

    for _ in 0..sample_count {
        let idx = usize::min(cursor as usize, count - 1);
        let start = idx * DIM;
        sample.extend_from_slice(&vectors[start..start + DIM]);
        cursor += step;
    }

    sample
}

fn run_kmeans(data: &[f32], points: usize, clusters: usize, iterations: usize) -> Vec<f32> {
    let mut centroids = Vec::with_capacity(clusters * DIM);
    let step = points as f64 / clusters as f64;
    let mut cursor = 0.0f64;

    for _ in 0..clusters {
        let idx = usize::min(cursor as usize, points - 1);
        let start = idx * DIM;
        centroids.extend_from_slice(&data[start..start + DIM]);
        cursor += step;
    }

    let mut assignments = vec![0usize; points];

    for _ in 0..iterations {
        assignments
            .par_iter_mut()
            .enumerate()
            .for_each(|(point_idx, assignment)| {
                let start = point_idx * DIM;
                *assignment = nearest_centroid(&data[start..start + DIM], &centroids, clusters);
            });

        let mut sums = vec![0.0f64; clusters * DIM];
        let mut counts = vec![0usize; clusters];

        for (point_idx, &cluster_id) in assignments.iter().enumerate() {
            counts[cluster_id] += 1;
            let src = point_idx * DIM;
            let dst = cluster_id * DIM;
            for dim in 0..DIM {
                sums[dst + dim] += data[src + dim] as f64;
            }
        }

        for cluster_id in 0..clusters {
            let count = counts[cluster_id];
            if count == 0 {
                continue;
            }

            let inv = 1.0f64 / count as f64;
            let start = cluster_id * DIM;
            for dim in 0..DIM {
                centroids[start + dim] = (sums[start + dim] * inv) as f32;
            }
        }
    }

    centroids
}

fn duplicate_centroid(centroid: &[f32], count: usize) -> Vec<f32> {
    let mut result = Vec::with_capacity(count * DIM);
    for _ in 0..count {
        result.extend_from_slice(centroid);
    }
    result
}

fn expand_bucket_centroids(bucket: &[f32], fallback: &[f32]) -> Vec<f32> {
    let points = bucket.len() / DIM;
    let mut result = Vec::with_capacity(SECONDARY_CLUSTERS * DIM);

    for idx in 0..SECONDARY_CLUSTERS {
        if idx < points {
            let start = idx * DIM;
            result.extend_from_slice(&bucket[start..start + DIM]);
        } else {
            result.extend_from_slice(fallback);
        }
    }

    result
}

#[inline(always)]
fn scan_cluster(query: &[f32], vectors: &[f32], ids: &[u64], topk: &mut TopK) {
    for (idx, vector) in vectors.chunks_exact(DIM).enumerate() {
        let distance = distance::l2_squared(query, vector);
        topk.push(ids[idx], distance);
    }
}

#[inline(always)]
fn push_smallest(
    ids: &mut [usize],
    distances: &mut [f32],
    len: &mut usize,
    id: usize,
    distance: f32,
) {
    if *len < ids.len() {
        ids[*len] = id;
        distances[*len] = distance;
        *len += 1;
        return;
    }

    let mut worst_idx = 0usize;
    for idx in 1..*len {
        if distances[idx] > distances[worst_idx] {
            worst_idx = idx;
        }
    }

    if distance < distances[worst_idx] {
        ids[worst_idx] = id;
        distances[worst_idx] = distance;
    }
}

fn sort_pairs(ids: &mut [usize], distances: &mut [f32], len: usize) {
    for i in 1..len {
        let id = ids[i];
        let distance = distances[i];
        let mut j = i;
        while j > 0 && distances[j - 1] > distance {
            ids[j] = ids[j - 1];
            distances[j] = distances[j - 1];
            j -= 1;
        }
        ids[j] = id;
        distances[j] = distance;
    }
}

pub const DIM: usize = 128;

#[inline(always)]
pub fn l2_distance(a: &[f32], b: &[f32]) -> f64 {
    l2_squared(a, b) as f64
}

#[inline(always)]
pub fn l2_squared(a: &[f32], b: &[f32]) -> f32 {
    debug_assert_eq!(a.len(), DIM);
    debug_assert_eq!(b.len(), DIM);

    #[cfg(target_arch = "x86_64")]
    {
        if is_x86_feature_detected!("avx512f") {
            return unsafe { l2_squared_avx512(a, b) };
        }
    }

    l2_squared_scalar(a, b)
}

#[inline(always)]
pub fn nearest_centroid(query: &[f32], centroids_flat: &[f32], count: usize) -> usize {
    debug_assert_eq!(query.len(), DIM);
    debug_assert!(centroids_flat.len() >= count * DIM);

    let mut best_idx = 0usize;
    let mut best_dist = f32::MAX;

    for idx in 0..count {
        let start = idx * DIM;
        let dist = l2_squared(query, &centroids_flat[start..start + DIM]);
        if dist < best_dist {
            best_dist = dist;
            best_idx = idx;
        }
    }

    best_idx
}

#[inline(always)]
pub fn l2_distance_batch(
    query: &[f32],
    vectors_flat: &[f32],
    n_vectors: usize,
    distances: &mut [f32],
) {
    debug_assert_eq!(query.len(), DIM);
    debug_assert!(vectors_flat.len() >= n_vectors * DIM);
    debug_assert!(distances.len() >= n_vectors);

    #[cfg(target_arch = "x86_64")]
    {
        if is_x86_feature_detected!("avx512f") {
            unsafe { l2_distance_batch_avx512(query, vectors_flat, n_vectors, distances) };
            return;
        }
    }

    for idx in 0..n_vectors {
        let start = idx * DIM;
        distances[idx] = l2_squared_scalar(query, &vectors_flat[start..start + DIM]);
    }
}

#[inline(always)]
fn l2_squared_scalar(a: &[f32], b: &[f32]) -> f32 {
    let mut sum = 0.0f32;

    for idx in 0..DIM {
        let delta = a[idx] - b[idx];
        sum += delta * delta;
    }

    sum
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx512f")]
unsafe fn l2_squared_avx512(a: &[f32], b: &[f32]) -> f32 {
    use std::arch::x86_64::*;

    let a_ptr = a.as_ptr();
    let b_ptr = b.as_ptr();

    let d0 = _mm512_sub_ps(_mm512_loadu_ps(a_ptr), _mm512_loadu_ps(b_ptr));
    let mut sum = _mm512_mul_ps(d0, d0);

    let d1 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(16)),
        _mm512_loadu_ps(b_ptr.add(16)),
    );
    sum = _mm512_fmadd_ps(d1, d1, sum);

    let d2 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(32)),
        _mm512_loadu_ps(b_ptr.add(32)),
    );
    sum = _mm512_fmadd_ps(d2, d2, sum);

    let d3 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(48)),
        _mm512_loadu_ps(b_ptr.add(48)),
    );
    sum = _mm512_fmadd_ps(d3, d3, sum);

    let d4 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(64)),
        _mm512_loadu_ps(b_ptr.add(64)),
    );
    sum = _mm512_fmadd_ps(d4, d4, sum);

    let d5 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(80)),
        _mm512_loadu_ps(b_ptr.add(80)),
    );
    sum = _mm512_fmadd_ps(d5, d5, sum);

    let d6 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(96)),
        _mm512_loadu_ps(b_ptr.add(96)),
    );
    sum = _mm512_fmadd_ps(d6, d6, sum);

    let d7 = _mm512_sub_ps(
        _mm512_loadu_ps(a_ptr.add(112)),
        _mm512_loadu_ps(b_ptr.add(112)),
    );
    sum = _mm512_fmadd_ps(d7, d7, sum);

    _mm512_reduce_add_ps(sum)
}

#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx512f")]
unsafe fn l2_distance_batch_avx512(
    query: &[f32],
    vectors_flat: &[f32],
    n_vectors: usize,
    distances: &mut [f32],
) {
    use std::arch::x86_64::*;

    let q_ptr = query.as_ptr();
    let q0 = _mm512_loadu_ps(q_ptr);
    let q1 = _mm512_loadu_ps(q_ptr.add(16));
    let q2 = _mm512_loadu_ps(q_ptr.add(32));
    let q3 = _mm512_loadu_ps(q_ptr.add(48));
    let q4 = _mm512_loadu_ps(q_ptr.add(64));
    let q5 = _mm512_loadu_ps(q_ptr.add(80));
    let q6 = _mm512_loadu_ps(q_ptr.add(96));
    let q7 = _mm512_loadu_ps(q_ptr.add(112));

    let v_ptr = vectors_flat.as_ptr();

    for idx in 0..n_vectors {
        let base = v_ptr.add(idx * DIM);

        let d0 = _mm512_sub_ps(q0, _mm512_loadu_ps(base));
        let mut sum = _mm512_mul_ps(d0, d0);

        let d1 = _mm512_sub_ps(q1, _mm512_loadu_ps(base.add(16)));
        sum = _mm512_fmadd_ps(d1, d1, sum);

        let d2 = _mm512_sub_ps(q2, _mm512_loadu_ps(base.add(32)));
        sum = _mm512_fmadd_ps(d2, d2, sum);

        let d3 = _mm512_sub_ps(q3, _mm512_loadu_ps(base.add(48)));
        sum = _mm512_fmadd_ps(d3, d3, sum);

        let d4 = _mm512_sub_ps(q4, _mm512_loadu_ps(base.add(64)));
        sum = _mm512_fmadd_ps(d4, d4, sum);

        let d5 = _mm512_sub_ps(q5, _mm512_loadu_ps(base.add(80)));
        sum = _mm512_fmadd_ps(d5, d5, sum);

        let d6 = _mm512_sub_ps(q6, _mm512_loadu_ps(base.add(96)));
        sum = _mm512_fmadd_ps(d6, d6, sum);

        let d7 = _mm512_sub_ps(q7, _mm512_loadu_ps(base.add(112)));
        sum = _mm512_fmadd_ps(d7, d7, sum);

        distances[idx] = _mm512_reduce_add_ps(sum);
    }
}

