= self.entries.write().unwrap();\n        let before = entries.len();\n        for (id, vector) in vectors {\n            assert_eq!(vector.len(), 128, \"Vector must be 128-dimensional\");\n            entries.push(Entry { id, vector });\n        }\n        entries.len() - before\n    }\n\n    pub fn search(&self, vector: &[f32], top_k: u32) -> Vec<SearchResult> {\n        assert_eq!(vector.len(), 128, \"Query vector must be 128-dimensional\");\n        let entries = self.entries.read().unwrap();\n        let n = entries.len();\n        if n == 0 || top_k == 0 {\n            return Vec::new();\n        }\n\n        // Use a small fixed buffer for partial top-k to avoid full sort when possible.\n        // But for correctness and simplicity (and because recall must be exact),\n        // we compute all distances and then select top-k.\n        // We will try to make distance computation fast and the selection efficient.\n\n        // For better performance, we can use an order-statistic selection or a binary heap.\n        // Use a max-heap of size top_k to keep the smallest distances.\n        use std::cmp::Reverse;\n        use std::collections::BinaryHeap;\n\n        let k = top_k as usize;\n        let mut heap = BinaryHeap::with_capacity(k + 1);\n\n        // If the dataset is large, using Rayon for parallel distance computation helps.\n        // But aggregation into a single heap requires care. We'll do a simple serial version first,\n        // then try a parallel version using chunks and merge.\n\n        for entry in entries.iter() {\n            let d = crate::distance::l2_distance(vector, &entry.vector);\n            // Push (distance, id). We want min distances, so use Reverse or invert ordering.\n            // Use Reverse<f64> for min-heap behavior by distance, but we want a max-heap\n            // of the k smallest, so we store (d, id) and keep the largest of the k at the top.\n            // Use a tuple (OrderedFloat, id) to allow f64 in BinaryHeap.