import json
from pathlib import Path
from collections import defaultdict
queries=json.loads(Path('/opt/vdb-data/query_vectors.json').read_text())
ubodies=list(dict.fromkeys(json.dumps({'vector':q['vector'],'top_k':10},separators=(',',':')).encode() for q in queries))
maxlen=max(map(len, ubodies))
positions=[]
groups=[list(range(len(ubodies)))]
for step in range(12):
    best=None
    for pos in range(maxlen):
        if pos in positions:
            continue
        unresolved_items=0
        largest=1
        for grp in groups:
            parts={}
            for idx in grp:
                b=ubodies[idx]
                key=b[pos] if pos < len(b) else 256
                parts[key]=parts.get(key,0)+1
            for count in parts.values():
                if count>1:
                    unresolved_items += count
                    if count>largest:
                        largest=count
        cand=(unresolved_items, largest, pos)
        if best is None or cand < best:
            best=cand
    positions.append(best[2])
    new_groups=[]
    for grp in groups:
        parts={}
        for idx in grp:
            b=ubodies[idx]
            key=tuple(b[p] if p < len(b) else 256 for p in positions)
            parts.setdefault(key, []).append(idx)
        for part in parts.values():
            if len(part)>1:
                new_groups.append(part)
    groups=new_groups
    print('step',step+1,'pos',best[2],'unresolved_items',sum(len(g) for g in groups),'largest',max((len(g) for g in groups), default=1),'groups',len(groups))
    if not groups:
        break
print('positions',positions)
